import { GetAgeMap } from "#core/ui/shell/create-panels/age-civ-select-model.js";
import LiveEventManager from "#core/ui/shell/live-event-logic/live-event-logic.js";
import { DatabaseCache } from "#core/ui/utilities/utilities-data.js";

export enum OwnershipAction {
	None,
	IncludedWith,
	LinkAccount,
}

export interface OwnershipData {
	action: OwnershipAction;
	reason: string;
}

export interface LeaderData {
	leaderID: string;
	name: string;
	icon: string;
	description: string;
	quote: string;
	abilityTitle: string;
	abilityText: string;
	ageUnlocks: string[];
	unlocks: string[];
	nextReward?: LegendPathReward;
	playCount: number;
	level: number;
	currentXp: number;
	nextLevelXp: number;
	prevLevelXp: number;
	tags: string[];
	isLocked: boolean;
	isOwned: boolean;
	ownershipData?: OwnershipData;
	sortIndex: number;
}

export interface MementoData {
	value: string | null;
	name: string | null;
	description: string | null;
	functionalDescription?: string | null;
	icon: string | null;
}

export enum MementoSlotType {
	Major,
	Minor,
}

export interface MementoSlotData {
	gameParameter: string;
	slotType: MementoSlotType;
	isLocked: boolean;
	unlockReason: string;
	currentMemento: MementoData;
	availableMementos: MementoData[];
}

const funcDescName = GameSetup.findString("FunctionalDescription");

function resolveMemento(value: GameSetupDomainValue): MementoData {
	const funcDescProp = value.additionalProperties?.find((v) => v.name === funcDescName);

	return {
		value: value.value!.toString(),
		name: GameSetup.resolveString(value.name),
		description: GameSetup.resolveString(value.description),
		functionalDescription: funcDescProp?.value as string,
		icon: GameSetup.resolveString(value.icon),
	};
}

export function getMementoData(): MementoSlotData[] {
	const mementoSlotParameters = GameSetup.getMementoFilteredPlayerParameters(GameContext.localPlayerID);
	const mementoSlotMetadata = Online.Metaprogression.getMementoSlotData();
	const mementoData: MementoSlotData[] = [];

	for (const mementoSlotParam of mementoSlotParameters) {
		if (!mementoSlotParam.hidden && mementoSlotParam.invalidReason == GameSetupParameterInvalidReason.Valid) {
			const paramId = GameSetup.resolveString(mementoSlotParam.ID);
			const metadata = mementoSlotMetadata.find((m) => m.mementoTypeId == paramId);

			if (metadata) {
				// TODO: Determine locked status and unlock level based on entitlements, when memento slot entitlements are available.
				const isLocked = metadata.displayType == DisplayType.DISPLAY_LOCKED;
				const isMajor = paramId?.startsWith("PlayerMementoMajorSlot");

				const slotData: MementoSlotData = {
					gameParameter: GameSetup.resolveString(mementoSlotParam.ID) ?? "",
					slotType: isMajor ? MementoSlotType.Major : MementoSlotType.Minor,
					isLocked: isLocked,
					unlockReason: metadata.unlockTitle,
					currentMemento: resolveMemento(mementoSlotParam.value),
					availableMementos: isLocked ? [] : mementoSlotParam.domain.possibleValues!.map(resolveMemento),
				};

				if (slotData.currentMemento.name && slotData.currentMemento.name != "LOC_MEMENTO_NONE_NAME") {
					//Remove "LOC_" and "_NAME" from the memento's name string
					const mementoName = slotData.currentMemento.name.substring(
						4,
						slotData.currentMemento.name.length - 5,
					);

					//Set selected memento to "NONE" if it's not unlocked for the player or if the memento slot is locked.
					if (!Online.UserProfile.isRewardUnlocked(mementoName) || isLocked) {
						const noMemento: MementoData = {
							value: Locale.compose("LOC_MEMENTO_NONE_NAME"),
							name: "LOC_MEMENTO_NONE_NAME",
							description: "LOC_MEMENTO_NONE_DESCRIPTION",
							functionalDescription: null,
							icon: null,
						};
						slotData.currentMemento = noMemento;
					}
				}

				mementoData.push(slotData);
			} else {
				console.log(`Unable to find memento slot metadata for ${paramId}`);
			}
		}
	}

	return mementoData;
}

function getOwnershipAction(actionName: string) {
	switch (actionName) {
		case "LOC_LOCKED_INCLUDED_WITH_CONTENT":
			return OwnershipAction.IncludedWith;

		case "LOC_LOCKED_LINK_ACCOUNT":
			return OwnershipAction.LinkAccount;
	}

	return OwnershipAction.None;
}

const leaderData_DatabaseCache = new DatabaseCache("config");

// This is a stopgap measure before the data can be populated via the SetupParameters API.
let cachedLeaderData: LeaderData[] | null = null;
export function getLeaderData(Stylize = true): LeaderData[] {
	if (cachedLeaderData) {
		return cachedLeaderData;
	}

	// Invalidate cache after execution.
	queueMicrotask(() => {
		console.debug("Wiping leaderData");
		cachedLeaderData = null;
	});

	const p = UI.beginProfiling("getLeaderData");
	console.debug("Constructing Leader Data (Expensive)");
	const leaderData: LeaderData[] = [];
	const playerParameter = GameSetup.findPlayerParameter(GameContext.localPlayerID, "PlayerLeader");

	if (playerParameter) {
		// Additional queries
		const bonusItems = leaderData_DatabaseCache.query("select * from LeaderItems order by SortIndex");
		const tags = leaderData_DatabaseCache.query(
			"select * from LeaderTags inner join Tags on LeaderTags.TagType = Tags.TagType inner join TagCategories on Tags.TagCategoryType = TagCategories.TagCategoryType",
		);
		const unlocks = leaderData_DatabaseCache.query("select * from LeaderUnlocks order by SortIndex");

		// Commenting until table exists in database.
		const ownershipConditions = leaderData_DatabaseCache.query("select * from OwnershipConditions");
		const quotes = leaderData_DatabaseCache.query("select * from LeaderQuotes");
		const legendsPaths = Online.Metaprogression.getLegendPathsData();
		const ageMap = GetAgeMap();
		const victoryProgress = HallofFame.getLeaderProgress("RULESET_STANDARD");
		for (const leader of playerParameter.domain.possibleValues ?? []) {
			const leaderID = leader.value?.toString();
			const name = GameSetup.resolveString(leader.name);

			if (!leaderID || !name) {
				continue;
			}

			// Do not show leaders if they don't have a reason for being not-valid
			if (leader.invalidReason == GameSetupDomainValueInvalidReason.NotValid) {
				continue;
			}

			// check if leader live event is running, don't show random leader if so
			if (LiveEventManager.restrictToPreferredCivs() && leaderID == "RANDOM") {
				continue;
			}

			const domain = GameSetup.resolveString(leader.originDomain);
			const description = GameSetup.resolveString(leader.description) ?? "";
			const leaderQuotes = quotes?.filter((q) => q.LeaderType == leaderID);

			const quote = leaderQuotes && leaderQuotes.length > 0 ? (leaderQuotes[0].Quote as string) : undefined;

			const valueBonusItems = bonusItems.filter(
				(item) => item.LeaderType == leaderID && item.LeaderDomain == domain,
			);
			const valueTags = tags
				.filter(
					(tag) =>
						!tag.HideInDetails &&
						(tag.LeaderType as string) == leaderID &&
						(tag.LeaderDomain as string) == domain,
				)
				.map((tag) => Locale.compose(tag.Name as string));

			const valueUnlocks = unlocks.filter(
				(unlock) =>
					(unlock.LeaderType as string) == leaderID &&
					(unlock.LeaderDomain as string) == domain &&
					(!unlock.AgeDomain || unlock.AgeDomain == ageMap.get(unlock.AgeType as string)?.domain),
			);

			const formattedAgeUnlocks: string[] = [];
			const formattedUnlocks: string[] = [];

			//Sort leader age unlocks to display sequentially by age
			const ageOrder = Array.from(ageMap.keys());
			valueUnlocks.sort((a, b) => ageOrder.indexOf(a.AgeType as string) - ageOrder.indexOf(b.AgeType as string));

			for (const unlock of valueUnlocks) {
				const age = unlock.AgeDomain ? ageMap.get(unlock.AgeType as string) : undefined;

				if (age) {
					formattedAgeUnlocks.push(
						Locale.stylize("LOC_CREATE_GAME_UNLOCK_ITEM_IN_AGE", unlock.Name as string, age.name),
					);
				} else {
					formattedUnlocks.push(Locale.stylize("LOC_CREATE_GAME_UNLOCK_ITEM", unlock.Name as string));
				}
			}

			const trait = valueBonusItems.find((item) => (item.Kind as string) == "KIND_TRAIT");
			const abilityTitle = trait?.Name;
			const abilityText = trait?.Description;

			const progress = victoryProgress.find((p: HallofFameLeaderProgress) => p.leaderType == leaderID);
			const playCount = progress ? (progress.playCount as number) : 0;

			let icon: string | null = GameSetup.resolveString(leader.icon);

			if (!icon) {
				console.error(`leader-select-panel: getLeaderData(): DB icon reference for leader ${name} is null`);
				icon = "fs://game/base-standard/leader_portrait_unknown.png"; // fallback
			}

			const legendData = legendsPaths.find(
				(item) => item.legendPathName == `${leaderID.replace("LEADER_", "LEGEND_PATH_")}`,
			);
			const currentLevel = legendData?.currentLevel ?? 0;
			const nextReward = legendData?.rewards?.find((reward) => reward.level > currentLevel);

			const isLocked = leader.invalidReason != GameSetupDomainValueInvalidReason.Valid;
			const isOwned = leader.invalidReason != GameSetupDomainValueInvalidReason.NotValidOwnership;
			let ownershipData: OwnershipData | undefined = undefined;

			if (!isOwned) {
				const ownershipEntry = ownershipConditions?.find((o) => o.ItemType == leaderID);
				if (ownershipEntry) {
					ownershipData = {
						reason: (ownershipEntry.Action as string) ?? "",
						action: getOwnershipAction(ownershipEntry.Action as string),
					};
				}
			}

			leaderData.push({
				leaderID: leaderID,
				name: Locale.stylize(name),
				icon: icon,
				description: Stylize ? Locale.stylize((description as string) ?? "") : ((description as string) ?? ""),
				abilityTitle: Stylize
					? Locale.stylize((abilityTitle as string) ?? "")
					: ((abilityTitle as string) ?? ""),
				abilityText: Stylize ? Locale.stylize((abilityText as string) ?? "") : ((abilityText as string) ?? ""),
				ageUnlocks: formattedAgeUnlocks,
				unlocks: formattedUnlocks,
				nextReward: nextReward,
				playCount: playCount,
				level: currentLevel,
				currentXp: Number(legendData?.currentXp ?? 0),
				nextLevelXp: Number(legendData?.nextLevelXp ?? 0),
				prevLevelXp: Number(legendData?.prevLevelXp ?? 0),
				tags: valueTags,
				isLocked: isLocked,
				isOwned: isOwned,
				ownershipData: ownershipData,
				sortIndex: leader.sortIndex,
				quote: quote ? Locale.stylize(quote) : "",
			});
		}
	}

	leaderData.sort((a, b) => {
		if (a.sortIndex != b.sortIndex) {
			return a.sortIndex - b.sortIndex;
		} else {
			return Locale.compare(a.name, b.name);
		}
	});

	UI.endProfiling(p);

	cachedLeaderData = leaderData;
	return cachedLeaderData;
}
